select '8742d33d-ce80-57a0-a20b-a0a1b2651d3f', e.id, 'CN', (select id from public.content_components where code = 'CN.COMP.QUI'), 'qa_passed', 'discontinuous', '{"title":"Estados de la materia","text":null,"svg":null,"table":{"caption":"Puntos de fusión y de ebullición de algunas sustancias a 1 atmósfera de presión","headers":["Sustancia","Punto de fusión (°C)","Punto de ebullición (°C)"],"rows":[["Agua",0,100],["Etanol",-114,78],["Mercurio",-39,357],["Hierro",1538,2862],["Oxígeno",-218,-183]]}}'::jsonb, '¿Cuál de estas sustancias es un gas a 25 °C?', '[{"label":"A","text":"Hierro.","is_correct":false,"distractor_type":"No compara la temperatura con los puntos de cambio.","explanation_feedback":"Incorrecta. A 25 °C el hierro está por debajo de 1538 °C: es sólido."},{"label":"B","text":"Mercurio.","is_correct":false,"distractor_type":"No compara la temperatura con los puntos de cambio.","explanation_feedback":"Incorrecta. A 25 °C el mercurio está entre −39 y 357 °C: es líquido."},{"label":"C","text":"Oxígeno.","is_correct":true,"distractor_type":null,"explanation_feedback":"Correcta. Su punto de ebullición es −183 °C; a 25 °C ya está por encima, así que es gas."},{"label":"D","text":"Etanol.","is_correct":false,"distractor_type":"No compara la temperatura con los puntos de cambio.","explanation_feedback":"Incorrecta. A 25 °C el etanol está entre −114 y 78 °C: es líquido."}]'::jsonb, null, 0.9, -1.2, 0.25, 50, 'original_generated'
