select '93367165-3604-5341-a33b-4ed6064a35cc', e.id, 'CN', (select id from public.content_components where code = 'CN.COMP.QUI'), 'qa_passed', 'discontinuous', '{"title":"Estados de la materia","text":null,"svg":null,"table":{"caption":"Puntos de fusión y de ebullición de algunas sustancias a 1 atmósfera de presión","headers":["Sustancia","Punto de fusión (°C)","Punto de ebullición (°C)"],"rows":[["Agua",0,100],["Etanol",-114,78],["Mercurio",-39,357],["Hierro",1538,2862],["Oxígeno",-218,-183]]}}'::jsonb, '¿En qué estado se encuentra el etanol a 90 °C?', '[{"label":"A","text":"Gaseoso, porque 90 °C supera su punto de ebullición.","is_correct":true,"distractor_type":null,"explanation_feedback":"Correcta. El etanol hierve a 78 °C; a 90 °C ya pasó a gas."},{"label":"B","text":"Líquido, porque 90 °C es menor que 100 °C.","is_correct":false,"distractor_type":"Usa el punto de ebullición del agua para el etanol.","explanation_feedback":"Incorrecta. 100 °C es del agua; el etanol hierve a 78 °C."},{"label":"C","text":"No se puede saber con la tabla.","is_correct":false,"distractor_type":"No usa la información de la tabla.","explanation_feedback":"Incorrecta. La tabla da el punto de ebullición, que permite saberlo."},{"label":"D","text":"Sólido, porque su punto de fusión es negativo.","is_correct":false,"distractor_type":"Interpreta al revés el punto de fusión.","explanation_feedback":"Incorrecta. Un punto de fusión de −114 °C indica que a temperaturas mayores ya no es sólido."}]'::jsonb, null, 1.1, 0, 0.25, 60, 'original_generated'
