select 'dcab8bff-5125-5c3f-89c3-f968ea86fe39', e.id, 'CN', (select id from public.content_components where code = 'CN.COMP.QUI'), 'qa_passed', 'discontinuous', '{"title":"Estados de la materia","text":null,"svg":null,"table":{"caption":"Puntos de fusión y de ebullición de algunas sustancias a 1 atmósfera de presión","headers":["Sustancia","Punto de fusión (°C)","Punto de ebullición (°C)"],"rows":[["Agua",0,100],["Etanol",-114,78],["Mercurio",-39,357],["Hierro",1538,2862],["Oxígeno",-218,-183]]}}'::jsonb, 'En un lugar donde la temperatura baja a −50 °C, ¿qué sustancias de la tabla serían sólidas?', '[{"label":"A","text":"Solo el hierro.","is_correct":false,"distractor_type":"Olvida que el agua y el mercurio también se congelan.","explanation_feedback":"Incorrecta. El agua se congela a 0 °C y el mercurio a −39 °C, ambos por encima de −50 °C."},{"label":"B","text":"Agua, mercurio y hierro.","is_correct":true,"distractor_type":null,"explanation_feedback":"Correcta. Las tres tienen punto de fusión mayor que −50 °C, así que a esa temperatura son sólidas."},{"label":"C","text":"Todas las sustancias de la tabla.","is_correct":false,"distractor_type":"No compara los puntos de fusión.","explanation_feedback":"Incorrecta. Etanol y oxígeno siguen sin solidificarse a −50 °C."},{"label":"D","text":"Agua, etanol y oxígeno.","is_correct":false,"distractor_type":"Confunde el orden de los valores negativos.","explanation_feedback":"Incorrecta. El etanol funde a −114 °C y el oxígeno a −218 °C: a −50 °C no son sólidos."}]'::jsonb, null, 1.1, 0, 0.25, 75, 'original_generated'
