select '269ab707-0dc8-5758-ba98-a93311843d65', e.id, 'CN', (select id from public.content_components where code = 'CN.COMP.QUI'), 'qa_passed', 'continuous', '{"title":"Agua, arena y sal","text":"Un estudiante tiene una mezcla de arena, sal y agua. Quiere recuperar por separado la arena y la sal. Dispone de un embudo con papel filtro, un recipiente para calentar y un mechero.","svg":null,"table":null}'::jsonb, '¿Qué orden de procedimientos le permite separar la arena y la sal?', '[{"label":"A","text":"Evaporar primero y luego filtrar la sal.","is_correct":false,"distractor_type":"Invierte el orden.","explanation_feedback":"Incorrecta. Si evapora primero, la sal y la arena quedan juntas como sólidos."},{"label":"B","text":"Calentar la mezcla para que la arena se disuelva.","is_correct":false,"distractor_type":"Supone que la arena es soluble.","explanation_feedback":"Incorrecta. La arena no se disuelve en agua al calentarla."},{"label":"C","text":"Filtrar para retener la arena y luego evaporar el agua para obtener la sal.","is_correct":true,"distractor_type":null,"explanation_feedback":"Correcta. La arena no se disuelve y queda en el filtro; la sal disuelta pasa y queda sola al evaporar el agua."},{"label":"D","text":"Filtrar dos veces para retener la sal.","is_correct":false,"distractor_type":"Supone que la sal disuelta queda en el filtro.","explanation_feedback":"Incorrecta. La sal disuelta atraviesa el filtro con el agua."}]'::jsonb, null, 1.1, 0, 0.25, 75, 'original_generated'
