select '4bf17524-5825-52fc-901e-205274a05b20', e.id, 'CN', (select id from public.content_components where code = 'CN.COMP.QUI'), 'qa_passed', 'continuous', '{"title":"Agua, arena y sal","text":"Un estudiante tiene una mezcla de arena, sal y agua. Quiere recuperar por separado la arena y la sal. Dispone de un embudo con papel filtro, un recipiente para calentar y un mechero.","svg":null,"table":null}'::jsonb, '¿Qué tipo de mezcla forman la arena y el agua?', '[{"label":"A","text":"Heterogénea, porque se distinguen sus componentes.","is_correct":true,"distractor_type":null,"explanation_feedback":"Correcta. La arena se ve y se deposita en el fondo: los componentes no se mezclan uniformemente."},{"label":"B","text":"Homogénea, porque es un solo líquido.","is_correct":false,"distractor_type":"Confunde con una disolución.","explanation_feedback":"Incorrecta. Se ven partículas de arena separadas del agua."},{"label":"C","text":"Un elemento, porque es natural.","is_correct":false,"distractor_type":"Confunde elemento con sustancia natural.","explanation_feedback":"Incorrecta. Un elemento está formado por un solo tipo de átomo."},{"label":"D","text":"Un compuesto, porque están juntas.","is_correct":false,"distractor_type":"Confunde mezcla con compuesto.","explanation_feedback":"Incorrecta. Un compuesto tiene composición fija y unión química."}]'::jsonb, null, 0.9, -1.2, 0.25, 45, 'original_generated'
