insert into public.questions (id, evidence_id, subject_id, component_id, status, context_type, context_content, stem, options, cefr_level, irt_a, irt_b, irt_c, estimated_time_seconds, origin)
select '6b03ed86-95a4-5093-9ad4-9ad9230dd8eb', e.id, 'CN', (select id from public.content_components where code = 'CN.COMP.QUI'), 'qa_passed', 'continuous', '{"title":"Agua, arena y sal","text":"Un estudiante tiene una mezcla de arena, sal y agua. Quiere recuperar por separado la arena y la sal. Dispone de un embudo con papel filtro, un recipiente para calentar y un mechero.","svg":null,"table":null}'::jsonb, '¿Qué propiedad hace posible separar la sal del agua por evaporación?', '[{"label":"A","text":"El agua es un elemento y la sal un compuesto.","is_correct":false,"distractor_type":"Clasifica mal el agua.","explanation_feedback":"Incorrecta. El agua es un compuesto (H₂O)."},{"label":"B","text":"El agua tiene un punto de ebullición mucho menor que el de la sal.","is_correct":true,"distractor_type":null,"explanation_feedback":"Correcta. Al calentar, el agua pasa a vapor mucho antes de que la sal cambie de estado."},{"label":"C","text":"La sal no se disuelve en el agua.","is_correct":false,"distractor_type":"Contradice el hecho de que la sal se disuelve.","explanation_feedback":"Incorrecta. La sal sí se disuelve; por eso no se separa al filtrar."},{"label":"D","text":"La sal es más liviana que el agua.","is_correct":false,"distractor_type":"Usa la densidad para un proceso que depende de la ebullición.","explanation_feedback":"Incorrecta. La evaporación depende de los puntos de ebullición, no de qué tan liviana sea la sal."}]'::jsonb, null, 1.3, 1.3, 0.25, 75, 'original_generated'
