insert into public.questions (id, evidence_id, subject_id, component_id, status, context_type, context_content, stem, options, cefr_level, irt_a, irt_b, irt_c, estimated_time_seconds, origin)
select 'bfba917e-aebb-5d44-a64d-63056f012137', e.id, 'CN', (select id from public.content_components where code = 'CN.COMP.QUI'), 'qa_passed', 'continuous', '{"title":"La combustión del gas natural","text":"El gas natural está formado principalmente por metano (CH₄). Cuando arde en una estufa reacciona con el oxígeno del aire según la ecuación:\nCH₄ + 2 O₂ → CO₂ + 2 H₂O\nMasas aproximadas: CH₄ = 16 g/mol, O₂ = 32 g/mol, CO₂ = 44 g/mol, H₂O = 18 g/mol.","svg":null,"table":null}'::jsonb, 'Si reaccionan 16 g de metano con 64 g de oxígeno, ¿cuál es la masa total de los productos?', '[{"label":"A","text":"16 g.","is_correct":false,"distractor_type":"Considera solo el metano.","explanation_feedback":"Incorrecta. Los productos incluyen la masa del oxígeno que reaccionó."},{"label":"B","text":"44 g.","is_correct":false,"distractor_type":"Considera solo el CO₂.","explanation_feedback":"Incorrecta. Hay que sumar también el agua: 44 + 36 = 80 g."},{"label":"C","text":"48 g.","is_correct":false,"distractor_type":"Resta en lugar de sumar.","explanation_feedback":"Incorrecta. La masa se conserva: no se resta."},{"label":"D","text":"80 g.","is_correct":true,"distractor_type":null,"explanation_feedback":"Correcta. Por la conservación de la masa, los productos pesan lo mismo que los reactivos: 16 + 64 = 80 g."}]'::jsonb, null, 1.1, 0, 0.25, 60, 'original_generated'
from public.evidences e where e.code = 'CN.E4.6'
on conflict (id) do nothing;
insert into public.questions (id, evidence_id, subject_id, component_id, status, context_type, context_content, stem, options, cefr_level, irt_a, irt_b, irt_c, estimated_time_seconds, origin)
select 'baf3e47f-7e61-5d8e-a951-7091c92dc435', e.id, 'CN', (select id from public.content_components where code = 'CN.COMP.QUI'), 'qa_passed', 'continuous', '{"title":"La combustión del gas natural","text":"El gas natural está formado principalmente por metano (CH₄). Cuando arde en una estufa reacciona con el oxígeno del aire según la ecuación:\nCH₄ + 2 O₂ → CO₂ + 2 H₂O\nMasas aproximadas: CH₄ = 16 g/mol, O₂ = 32 g/mol, CO₂ = 44 g/mol, H₂O = 18 g/mol.","svg":null,"table":null}'::jsonb, '¿Por qué la ecuación tiene un 2 delante del O₂ y del H₂O?', '[{"label":"A","text":"Porque el metano tiene dos átomos de carbono.","is_correct":false,"distractor_type":"Lee mal la fórmula.","explanation_feedback":"Incorrecta. El metano tiene un átomo de carbono."},{"label":"B","text":"Para indicar que la reacción ocurre dos veces.","is_correct":false,"distractor_type":"Interpreta mal el coeficiente.","explanation_feedback":"Incorrecta. El coeficiente indica la proporción de moléculas, no repeticiones."},{"label":"C","text":"Porque el oxígeno siempre se escribe con un 2 delante.","is_correct":false,"distractor_type":"Generaliza una regla inexistente.","explanation_feedback":"Incorrecta. El coeficiente depende del balance de cada ecuación."},{"label":"D","text":"Para que haya el mismo número de átomos de cada elemento a ambos lados.","is_correct":true,"distractor_type":null,"explanation_feedback":"Correcta. Con esos coeficientes hay 1 C, 4 H y 4 O en reactivos y productos."}]'::jsonb, null, 1.1, 0, 0.25, 60, 'original_generated'
from public.evidences e where e.code = 'CN.E2.1'
on conflict (id) do nothing;
insert into public.questions (id, evidence_id, subject_id, component_id, status, context_type, context_content, stem, options, cefr_level, irt_a, irt_b, irt_c, estimated_time_seconds, origin)
select '7465fd44-ac9c-5082-ba1d-e09c1daa503f', e.id, 'CN', (select id from public.content_components where code = 'CN.COMP.QUI'), 'qa_passed', 'continuous', '{"title":"La combustión del gas natural","text":"El gas natural está formado principalmente por metano (CH₄). Cuando arde en una estufa reacciona con el oxígeno del aire según la ecuación:\nCH₄ + 2 O₂ → CO₂ + 2 H₂O\nMasas aproximadas: CH₄ = 16 g/mol, O₂ = 32 g/mol, CO₂ = 44 g/mol, H₂O = 18 g/mol.","svg":null,"table":null}'::jsonb, '¿Cuántos gramos de agua se producen al quemar por completo 32 g de metano?', '[{"label":"A","text":"36 g.","is_correct":false,"distractor_type":"Calcula para 16 g de metano.","explanation_feedback":"Incorrecta. Con 16 g se producen 36 g; con el doble de metano, el doble de agua."},{"label":"B","text":"72 g.","is_correct":true,"distractor_type":null,"explanation_feedback":"Correcta. 32 g son 2 mol de CH₄; cada mol produce 2 mol de H₂O, es decir 4 mol × 18 g/mol = 72 g."},{"label":"C","text":"88 g.","is_correct":false,"distractor_type":"Calcula la masa de CO₂.","explanation_feedback":"Incorrecta. 88 g sería el CO₂ producido por 2 mol de metano."},{"label":"D","text":"18 g.","is_correct":false,"distractor_type":"Toma una sola molécula de agua por mol de metano.","explanation_feedback":"Incorrecta. La ecuación muestra 2 H₂O por cada CH₄."}]'::jsonb, null, 1.3, 1.3, 0.25, 90, 'original_generated'
from public.evidences e where e.code = 'CN.E4.6'
on conflict (id) do nothing;
