select 'ff3d5f66-1786-523b-b71b-588e54e29db1', e.id, 'CN', (select id from public.content_components where code = 'CN.COMP.QUI'), 'qa_passed', 'continuous', '{"title":"La combustión del gas natural","text":"El gas natural está formado principalmente por metano (CH₄). Cuando arde en una estufa reacciona con el oxígeno del aire según la ecuación:\nCH₄ + 2 O₂ → CO₂ + 2 H₂O\nMasas aproximadas: CH₄ = 16 g/mol, O₂ = 32 g/mol, CO₂ = 44 g/mol, H₂O = 18 g/mol.","svg":null,"table":null}'::jsonb, '¿Por qué es peligroso usar una estufa de gas en un cuarto sin ventilación?', '[{"label":"A","text":"Porque el agua producida inunda el cuarto.","is_correct":false,"distractor_type":"Exagera la cantidad de agua.","explanation_feedback":"Incorrecta. El agua sale como vapor en pequeñas cantidades."},{"label":"B","text":"Porque si falta oxígeno la combustión es incompleta y produce monóxido de carbono, un gas tóxico.","is_correct":true,"distractor_type":null,"explanation_feedback":"Correcta. Con poco oxígeno se forma CO, que impide que la sangre transporte oxígeno."},{"label":"C","text":"Porque la llama enfría demasiado el cuarto.","is_correct":false,"distractor_type":"Contradice el fenómeno.","explanation_feedback":"Incorrecta. La combustión libera calor."},{"label":"D","text":"Porque el metano se convierte en oxígeno.","is_correct":false,"distractor_type":"Invierte la reacción.","explanation_feedback":"Incorrecta. La reacción consume oxígeno."}]'::jsonb, null, 1.1, 0, 0.25, 60, 'original_generated'
from public.evidences e where e.code = 'CN.E1.1'
