select '87518d01-5ac9-5b30-9c8e-9a2681c03f82', e.id, 'CN', (select id from public.content_components where code = 'CN.COMP.QUI'), 'qa_passed', 'discontinuous', '{"title":"La escala de pH","text":null,"svg":null,"table":{"caption":"pH aproximado de algunas sustancias a 25 °C","headers":["Sustancia","pH"],"rows":[["Jugo de limón",2],["Vinagre",3],["Café",5],["Agua pura",7],["Agua de mar",8],["Bicarbonato disuelto",9],["Limpiador con amoníaco",11]]}}'::jsonb, '¿Cuál de estas sustancias es la más ácida?', '[{"label":"A","text":"El café.","is_correct":false,"distractor_type":"No compara todos los valores.","explanation_feedback":"Incorrecta. El café (pH 5) es menos ácido que el limón."},{"label":"B","text":"El jugo de limón.","is_correct":true,"distractor_type":null,"explanation_feedback":"Correcta. Tiene el pH más bajo de la tabla (2); a menor pH, mayor acidez."},{"label":"C","text":"El limpiador.","is_correct":false,"distractor_type":"Interpreta al revés la escala.","explanation_feedback":"Incorrecta. Un pH de 11 indica una sustancia básica."},{"label":"D","text":"Agua pura.","is_correct":false,"distractor_type":"Confunde neutro con ácido.","explanation_feedback":"Incorrecta. El agua pura tiene pH 7, es neutra."}]'::jsonb, null, 0.9, -1.2, 0.25, 40, 'original_generated'
