insert into public.questions (id, evidence_id, subject_id, component_id, status, context_type, context_content, stem, options, cefr_level, irt_a, irt_b, irt_c, estimated_time_seconds, origin)
select 'ae6fa381-ba61-52e5-904a-f06437433366', e.id, 'CN', (select id from public.content_components where code = 'CN.COMP.QUI'), 'qa_passed', 'discontinuous', '{"title":"La escala de pH","text":null,"svg":null,"table":{"caption":"pH aproximado de algunas sustancias a 25 °C","headers":["Sustancia","pH"],"rows":[["Jugo de limón",2],["Vinagre",3],["Café",5],["Agua pura",7],["Agua de mar",8],["Bicarbonato disuelto",9],["Limpiador con amoníaco",11]]}}'::jsonb, 'Una persona con acidez estomacal toma bicarbonato disuelto. ¿Qué ocurre?', '[{"label":"A","text":"El estómago se vuelve neutro para siempre.","is_correct":false,"distractor_type":"Exagera el efecto.","explanation_feedback":"Incorrecta. El estómago sigue produciendo ácido."},{"label":"B","text":"El bicarbonato, que es básico, neutraliza parte del ácido del estómago.","is_correct":true,"distractor_type":null,"explanation_feedback":"Correcta. Una base reacciona con un ácido y reduce la acidez."},{"label":"C","text":"El bicarbonato aumenta la acidez porque su pH es alto.","is_correct":false,"distractor_type":"Interpreta al revés la escala.","explanation_feedback":"Incorrecta. Un pH alto indica base, que reduce la acidez."},{"label":"D","text":"No pasa nada, porque las bases y los ácidos no reaccionan.","is_correct":false,"distractor_type":"Desconoce la neutralización.","explanation_feedback":"Incorrecta. Ácidos y bases reaccionan entre sí."}]'::jsonb, null, 1.1, 0, 0.25, 60, 'original_generated'
