insert into public.questions (id, evidence_id, subject_id, component_id, status, context_type, context_content, stem, options, cefr_level, irt_a, irt_b, irt_c, estimated_time_seconds, origin)
select 'bcdb86d5-6b82-5ee4-8c2f-265dedbc3a18', e.id, 'CN', (select id from public.content_components where code = 'CN.COMP.QUI'), 'qa_passed', 'discontinuous', '{"title":"La escala de pH","text":null,"svg":null,"table":{"caption":"pH aproximado de algunas sustancias a 25 °C","headers":["Sustancia","pH"],"rows":[["Jugo de limón",2],["Vinagre",3],["Café",5],["Agua pura",7],["Agua de mar",8],["Bicarbonato disuelto",9],["Limpiador con amoníaco",11]]}}'::jsonb, 'Si se mezclan volúmenes de vinagre y bicarbonato disuelto, ¿qué valor de pH es esperable para la mezcla?', '[{"label":"A","text":"Menor que 3, porque el vinagre es más fuerte.","is_correct":false,"distractor_type":"Supone que la mezcla se vuelve más ácida.","explanation_feedback":"Incorrecta. Agregar una base reduce la acidez."},{"label":"B","text":"Exactamente 12, porque se suman los pH.","is_correct":false,"distractor_type":"Suma los valores de pH.","explanation_feedback":"Incorrecta. El pH no es aditivo."},{"label":"C","text":"Mayor que 9, porque el bicarbonato domina.","is_correct":false,"distractor_type":"Supone que la mezcla se vuelve más básica que la base.","explanation_feedback":"Incorrecta. Agregar un ácido reduce la basicidad."},{"label":"D","text":"Uno entre 3 y 9, más cercano a 7 que el de cada sustancia por separado.","is_correct":true,"distractor_type":null,"explanation_feedback":"Correcta. Al neutralizarse en parte, el pH de la mezcla queda entre los dos valores iniciales."}]'::jsonb, null, 1.3, 1.3, 0.25, 75, 'original_generated'
