select '93d63afc-94a6-5a9d-952d-1075d0c81bbb', e.id, 'CN', (select id from public.content_components where code = 'CN.COMP.QUI'), 'qa_passed', 'discontinuous', '{"title":"Solubilidad y temperatura","text":null,"svg":null,"table":{"caption":"Masa máxima de nitrato de potasio que se disuelve en 100 g de agua (valores aproximados)","headers":["Temperatura (°C)","Nitrato de potasio disuelto (g)"],"rows":[[20,32],[40,64],[60,110],[80,169]]}}'::jsonb, '¿Qué relación muestra la tabla?', '[{"label":"A","text":"Al aumentar la temperatura, se disuelve menos.","is_correct":false,"distractor_type":"Lee al revés la tabla.","explanation_feedback":"Incorrecta. Los valores aumentan con la temperatura."},{"label":"B","text":"Solo se disuelve por encima de 60 °C.","is_correct":false,"distractor_type":"Ignora los primeros datos.","explanation_feedback":"Incorrecta. A 20 °C ya se disuelven 32 g."},{"label":"C","text":"La temperatura no afecta la cantidad disuelta.","is_correct":false,"distractor_type":"Ignora la variación de los datos.","explanation_feedback":"Incorrecta. Los valores cambian mucho con la temperatura."},{"label":"D","text":"Al aumentar la temperatura, se disuelve más nitrato de potasio.","is_correct":true,"distractor_type":null,"explanation_feedback":"Correcta. La masa disuelta crece de 32 g a 169 g cuando la temperatura sube de 20 a 80 °C."}]'::jsonb, null, 0.9, -1.2, 0.25, 45, 'original_generated'
