select '5795a087-2268-57a3-b4b3-79b191d2b83e', e.id, 'CN', (select id from public.content_components where code = 'CN.COMP.QUI'), 'qa_passed', 'discontinuous', '{"title":"Solubilidad y temperatura","text":null,"svg":null,"table":{"caption":"Masa máxima de nitrato de potasio que se disuelve en 100 g de agua (valores aproximados)","headers":["Temperatura (°C)","Nitrato de potasio disuelto (g)"],"rows":[[20,32],[40,64],[60,110],[80,169]]}}'::jsonb, 'Si se disuelven 100 g de nitrato de potasio en 100 g de agua a 60 °C y luego se enfría a 40 °C, ¿qué ocurre?', '[{"label":"A","text":"Se disuelve más sal al enfriar.","is_correct":false,"distractor_type":"Lee al revés la tabla.","explanation_feedback":"Incorrecta. A menor temperatura se disuelve menos."},{"label":"B","text":"No pasa nada, porque la sal ya estaba disuelta.","is_correct":false,"distractor_type":"Ignora que la solubilidad cambia al enfriar.","explanation_feedback":"Incorrecta. Al enfriar baja la cantidad que puede estar disuelta."},{"label":"C","text":"El agua se evapora por completo.","is_correct":false,"distractor_type":"Confunde enfriar con calentar.","explanation_feedback":"Incorrecta. Enfriar no evapora el agua."},{"label":"D","text":"Se forman cristales, porque a 40 °C solo caben 64 g disueltos.","is_correct":true,"distractor_type":null,"explanation_feedback":"Correcta. Sobran unos 36 g que ya no pueden estar disueltos y se separan como sólido."}]'::jsonb, null, 1.1, 0, 0.25, 75, 'original_generated'
