select 'fd3ab7c6-7a23-5f08-a3f7-81a8373efa68', e.id, 'CN', (select id from public.content_components where code = 'CN.COMP.QUI'), 'qa_passed', 'discontinuous', '{"title":"Solubilidad y temperatura","text":null,"svg":null,"table":{"caption":"Masa máxima de nitrato de potasio que se disuelve en 100 g de agua (valores aproximados)","headers":["Temperatura (°C)","Nitrato de potasio disuelto (g)"],"rows":[[20,32],[40,64],[60,110],[80,169]]}}'::jsonb, 'A diferencia de los sólidos de la tabla, el oxígeno se disuelve menos en agua caliente. ¿Qué consecuencia tiene esto para los peces cuando un río se calienta?', '[{"label":"A","text":"No les afecta, porque respiran aire de la superficie.","is_correct":false,"distractor_type":"Desconoce cómo respiran los peces.","explanation_feedback":"Incorrecta. Los peces toman el oxígeno disuelto con sus branquias."},{"label":"B","text":"El agua caliente produce oxígeno nuevo.","is_correct":false,"distractor_type":"Inventa un proceso.","explanation_feedback":"Incorrecta. Calentar el agua no produce oxígeno."},{"label":"C","text":"Disponen de más oxígeno porque el agua se mueve más.","is_correct":false,"distractor_type":"Aplica a los gases la tendencia de los sólidos.","explanation_feedback":"Incorrecta. Para los gases, el calor reduce la solubilidad."},{"label":"D","text":"Disponen de menos oxígeno disuelto para respirar.","is_correct":true,"distractor_type":null,"explanation_feedback":"Correcta. Si sube la temperatura, baja el oxígeno disuelto, y los peces pueden asfixiarse."}]'::jsonb, null, 1.3, 1.3, 0.25, 75, 'original_generated'
