select 'ce3a52b6-b9f1-5233-be62-64408fd07039', e.id, 'CN', (select id from public.content_components where code = 'CN.COMP.QUI'), 'qa_passed', 'continuous', '{"title":"Un globo en el congelador","text":"Una estudiante infla un globo a temperatura ambiente (25 °C) y lo mete en el congelador (−18 °C). Una hora después, el globo está más pequeño. Al sacarlo, vuelve poco a poco a su tamaño inicial.","svg":null,"table":null}'::jsonb, '¿Qué explica el cambio de tamaño del globo?', '[{"label":"A","text":"Las partículas de gas se hacen más pequeñas.","is_correct":false,"distractor_type":"Atribuye el cambio al tamaño de las partículas.","explanation_feedback":"Incorrecta. Lo que cambia es la energía y separación de las partículas, no su tamaño."},{"label":"B","text":"El aire se escapa por los poros del globo.","is_correct":false,"distractor_type":"Supone pérdida de gas.","explanation_feedback":"Incorrecta. Si el aire saliera, el globo no recuperaría su tamaño."},{"label":"C","text":"Al enfriarse el gas, sus partículas se mueven más lento y ocupa menos volumen.","is_correct":true,"distractor_type":null,"explanation_feedback":"Correcta. A presión casi constante, el volumen de un gas disminuye al bajar su temperatura."},{"label":"D","text":"El frío convierte el aire en agua.","is_correct":false,"distractor_type":"Confunde el gas con vapor.","explanation_feedback":"Incorrecta. El aire seco no se convierte en agua a −18 °C."}]'::jsonb, null, 1.1, 0, 0.25, 60, 'original_generated'
