select '402291a2-b23d-535e-b93c-82e624db3ee0', e.id, 'CN', (select id from public.content_components where code = 'CN.COMP.QUI'), 'qa_passed', 'continuous', '{"title":"Un globo en el congelador","text":"Una estudiante infla un globo a temperatura ambiente (25 °C) y lo mete en el congelador (−18 °C). Una hora después, el globo está más pequeño. Al sacarlo, vuelve poco a poco a su tamaño inicial.","svg":null,"table":null}'::jsonb, '¿Qué pregunta de investigación se puede responder con un experimento como este?', '[{"label":"A","text":"¿Por qué los globos son de colores?","is_correct":false,"distractor_type":"Formula una pregunta sin relación con la variable estudiada.","explanation_feedback":"Incorrecta. El color no se estudia en este experimento."},{"label":"B","text":"¿Qué opinan las personas sobre los globos?","is_correct":false,"distractor_type":"Formula una pregunta de opinión.","explanation_feedback":"Incorrecta. No se puede responder con mediciones de este experimento."},{"label":"C","text":"¿Cuál es el mejor congelador del mercado?","is_correct":false,"distractor_type":"Formula una pregunta comercial.","explanation_feedback":"Incorrecta. El experimento no compara congeladores."},{"label":"D","text":"¿Cómo cambia el volumen de un gas cuando cambia su temperatura?","is_correct":true,"distractor_type":null,"explanation_feedback":"Correcta. Se puede medir el tamaño del globo a diferentes temperaturas."}]'::jsonb, null, 1.3, 1.3, 0.25, 60, 'original_generated'
