select '33eeef7b-1b05-5d05-90db-faac0128d9e4', e.id, 'CN', (select id from public.content_components where code = 'CN.COMP.QUI'), 'qa_passed', 'continuous', '{"title":"Un globo en el congelador","text":"Una estudiante infla un globo a temperatura ambiente (25 °C) y lo mete en el congelador (−18 °C). Una hora después, el globo está más pequeño. Al sacarlo, vuelve poco a poco a su tamaño inicial.","svg":null,"table":null}'::jsonb, 'Una jeringa sellada contiene 40 mL de aire a 1 atmósfera. Si se empuja el émbolo hasta que la presión sea 2 atmósferas, sin cambiar la temperatura, ¿cuál será el volumen?', '[{"label":"A","text":"38 mL.","is_correct":false,"distractor_type":"Resta la presión al volumen.","explanation_feedback":"Incorrecta. La relación es un producto constante, no una resta."},{"label":"B","text":"40 mL.","is_correct":false,"distractor_type":"Supone que el volumen no cambia.","explanation_feedback":"Incorrecta. El aire se comprime al aumentar la presión."},{"label":"C","text":"20 mL.","is_correct":true,"distractor_type":null,"explanation_feedback":"Correcta. A temperatura constante, presión por volumen es constante: 1 × 40 = 2 × V, entonces V = 20 mL."},{"label":"D","text":"80 mL.","is_correct":false,"distractor_type":"Supone que volumen y presión son directamente proporcionales.","explanation_feedback":"Incorrecta. Al aumentar la presión, el volumen disminuye."}]'::jsonb, null, 1.3, 1.3, 0.25, 75, 'original_generated'
