select '31953c83-9cc7-576e-a1d5-c8c542d7f207', e.id, 'CN', (select id from public.content_components where code = 'CN.COMP.QUI'), 'qa_passed', 'continuous', '{"title":"Átomos e iones","text":"El sodio (Na) tiene número atómico 11: un átomo neutro tiene 11 protones y 11 electrones. El cloro (Cl) tiene número atómico 17. Cuando reaccionan, el sodio cede un electrón al cloro y se forman los iones Na⁺ y Cl⁻, que se unen en el cloruro de sodio, la sal de cocina.","svg":null,"table":null}'::jsonb, '¿Cuántos electrones tiene el ion Na⁺?', '[{"label":"A","text":"1.","is_correct":false,"distractor_type":"Confunde la carga con el número de electrones.","explanation_feedback":"Incorrecta. La carga +1 es la diferencia entre protones y electrones."},{"label":"B","text":"12.","is_correct":false,"distractor_type":"Interpreta la carga positiva como ganancia de electrones.","explanation_feedback":"Incorrecta. Una carga positiva significa que perdió electrones."},{"label":"C","text":"11.","is_correct":false,"distractor_type":"Olvida que el ion perdió un electrón.","explanation_feedback":"Incorrecta. El ion Na⁺ ya cedió un electrón."},{"label":"D","text":"10.","is_correct":true,"distractor_type":null,"explanation_feedback":"Correcta. El sodio neutro tiene 11 electrones y al ceder uno queda con 10; la carga positiva indica que tiene más protones que electrones."}]'::jsonb, null, 1.1, 0, 0.25, 50, 'original_generated'
from public.evidences e where e.code = 'CN.E4.8'
on conflict (id) do nothing;
