select '248c0664-d055-5903-88e4-d99051bd2cd5', e.id, 'CN', (select id from public.content_components where code = 'CN.COMP.QUI'), 'qa_passed', 'continuous', '{"title":"Átomos e iones","text":"El sodio (Na) tiene número atómico 11: un átomo neutro tiene 11 protones y 11 electrones. El cloro (Cl) tiene número atómico 17. Cuando reaccionan, el sodio cede un electrón al cloro y se forman los iones Na⁺ y Cl⁻, que se unen en el cloruro de sodio, la sal de cocina.","svg":null,"table":null}'::jsonb, '¿Cuántos protones tiene el ion Cl⁻?', '[{"label":"A","text":"1.","is_correct":false,"distractor_type":"Confunde la carga con el número de protones.","explanation_feedback":"Incorrecta. La carga es la diferencia entre protones y electrones."},{"label":"B","text":"16.","is_correct":false,"distractor_type":"Supone que perdió un protón.","explanation_feedback":"Incorrecta. En una reacción química los protones no cambian."},{"label":"C","text":"17.","is_correct":true,"distractor_type":null,"explanation_feedback":"Correcta. El número de protones no cambia al formar un ion: sigue siendo el número atómico, 17."},{"label":"D","text":"18.","is_correct":false,"distractor_type":"Confunde protones con electrones.","explanation_feedback":"Incorrecta. El Cl⁻ tiene 18 electrones, pero sigue con 17 protones."}]'::jsonb, null, 1.1, 0, 0.25, 50, 'original_generated'
