select '0d7afde0-a369-5042-af4e-a4e57faf4bb5', e.id, 'CN', (select id from public.content_components where code = 'CN.COMP.QUI'), 'qa_passed', 'continuous', '{"title":"Átomos e iones","text":"El sodio (Na) tiene número atómico 11: un átomo neutro tiene 11 protones y 11 electrones. El cloro (Cl) tiene número atómico 17. Cuando reaccionan, el sodio cede un electrón al cloro y se forman los iones Na⁺ y Cl⁻, que se unen en el cloruro de sodio, la sal de cocina.","svg":null,"table":null}'::jsonb, '¿Por qué la sal disuelta en agua conduce la electricidad y el azúcar disuelto no?', '[{"label":"A","text":"Porque la sal es un metal y el azúcar no.","is_correct":false,"distractor_type":"Clasifica mal la sal.","explanation_feedback":"Incorrecta. La sal es un compuesto iónico, no un metal."},{"label":"B","text":"Porque el azúcar no se disuelve en agua.","is_correct":false,"distractor_type":"Contradice un hecho cotidiano.","explanation_feedback":"Incorrecta. El azúcar sí se disuelve, pero sin formar iones."},{"label":"C","text":"Porque la sal forma iones libres y el azúcar forma moléculas neutras.","is_correct":true,"distractor_type":null,"explanation_feedback":"Correcta. Las cargas en movimiento permiten la corriente eléctrica."},{"label":"D","text":"Porque el azúcar es más dulce que la sal.","is_correct":false,"distractor_type":"Usa una propiedad sin relación.","explanation_feedback":"Incorrecta. El sabor no determina la conductividad."}]'::jsonb, null, 1.3, 1.3, 0.25, 75, 'original_generated'
