select '68a85ad3-95c1-5313-853a-006d7d354628', e.id, 'CN', (select id from public.content_components where code = 'CN.COMP.QUI'), 'qa_passed', 'continuous', '{"title":"Átomos e iones","text":"El sodio (Na) tiene número atómico 11: un átomo neutro tiene 11 protones y 11 electrones. El cloro (Cl) tiene número atómico 17. Cuando reaccionan, el sodio cede un electrón al cloro y se forman los iones Na⁺ y Cl⁻, que se unen en el cloruro de sodio, la sal de cocina.","svg":null,"table":null}'::jsonb, '¿Qué partícula del átomo tiene carga negativa?', '[{"label":"A","text":"El neutrón.","is_correct":false,"distractor_type":"Confunde las cargas.","explanation_feedback":"Incorrecta. El neutrón no tiene carga."},{"label":"B","text":"El protón.","is_correct":false,"distractor_type":"Confunde las cargas.","explanation_feedback":"Incorrecta. El protón tiene carga positiva."},{"label":"C","text":"El electrón.","is_correct":true,"distractor_type":null,"explanation_feedback":"Correcta. Los electrones tienen carga negativa; los protones, positiva, y los neutrones no tienen carga."},{"label":"D","text":"El núcleo.","is_correct":false,"distractor_type":"Confunde una región con una partícula.","explanation_feedback":"Incorrecta. El núcleo tiene carga positiva por sus protones."}]'::jsonb, null, 0.9, -1.2, 0.25, 35, 'original_generated'
