select 'b1f0eef2-5e32-53f7-a696-d7e71dc2d14c', e.id, 'CN', (select id from public.content_components where code = 'CN.COMP.QUI'), 'qa_passed', 'continuous', '{"title":"Tipos de reacciones","text":"Algunas reacciones químicas:\n1. 2 H₂ + O₂ → 2 H₂O\n2. CaCO₃ → CaO + CO₂ (al calentar)\n3. Zn + 2 HCl → ZnCl₂ + H₂\n4. AgNO₃ + NaCl → AgCl + NaNO₃","svg":null,"table":null}'::jsonb, '¿Cuál de las reacciones es de descomposición?', '[{"label":"A","text":"La 2.","is_correct":true,"distractor_type":null,"explanation_feedback":"Correcta. Una sola sustancia (CaCO₃) se separa en dos más simples."},{"label":"B","text":"La 1.","is_correct":false,"distractor_type":"Confunde síntesis con descomposición.","explanation_feedback":"Incorrecta. En la 1, dos sustancias se unen en una: es síntesis."},{"label":"C","text":"La 4.","is_correct":false,"distractor_type":"Confunde doble desplazamiento con descomposición.","explanation_feedback":"Incorrecta. En la 4, dos compuestos intercambian iones."},{"label":"D","text":"La 3.","is_correct":false,"distractor_type":"Confunde desplazamiento con descomposición.","explanation_feedback":"Incorrecta. En la 3, el zinc desplaza al hidrógeno."}]'::jsonb, null, 1.1, 0, 0.25, 60, 'original_generated'
