select '90ba1393-55fc-5e57-ab23-6a4ade92b7a7', e.id, 'CN', (select id from public.content_components where code = 'CN.COMP.QUI'), 'qa_passed', 'continuous', '{"title":"Tipos de reacciones","text":"Algunas reacciones químicas:\n1. 2 H₂ + O₂ → 2 H₂O\n2. CaCO₃ → CaO + CO₂ (al calentar)\n3. Zn + 2 HCl → ZnCl₂ + H₂\n4. AgNO₃ + NaCl → AgCl + NaNO₃","svg":null,"table":null}'::jsonb, '¿Qué tipo de reacción es la 1?', '[{"label":"A","text":"De doble desplazamiento.","is_correct":false,"distractor_type":"Confunde los tipos.","explanation_feedback":"Incorrecta. No hay intercambio de iones entre compuestos."},{"label":"B","text":"De síntesis, porque dos sustancias forman una sola.","is_correct":true,"distractor_type":null,"explanation_feedback":"Correcta. Hidrógeno y oxígeno se combinan para formar agua."},{"label":"C","text":"De descomposición, porque se forma agua.","is_correct":false,"distractor_type":"Confunde los tipos.","explanation_feedback":"Incorrecta. En la descomposición una sustancia se separa."},{"label":"D","text":"No es una reacción química.","is_correct":false,"distractor_type":"Desconoce el cambio químico.","explanation_feedback":"Incorrecta. Se forma una sustancia nueva: es una reacción."}]'::jsonb, null, 1.1, 0, 0.25, 50, 'original_generated'
