select '7e3b4299-4473-5458-aa7c-bbdd604ab667', e.id, 'CN', (select id from public.content_components where code = 'CN.COMP.QUI'), 'qa_passed', 'continuous', '{"title":"Tipos de reacciones","text":"Algunas reacciones químicas:\n1. 2 H₂ + O₂ → 2 H₂O\n2. CaCO₃ → CaO + CO₂ (al calentar)\n3. Zn + 2 HCl → ZnCl₂ + H₂\n4. AgNO₃ + NaCl → AgCl + NaNO₃","svg":null,"table":null}'::jsonb, 'En la reacción 3, ¿por qué el HCl lleva el coeficiente 2?', '[{"label":"A","text":"Para que la masa de los productos sea mayor.","is_correct":false,"distractor_type":"Contradice la conservación de la masa.","explanation_feedback":"Incorrecta. La masa debe ser igual a ambos lados."},{"label":"B","text":"Porque el ácido siempre reacciona dos veces.","is_correct":false,"distractor_type":"Inventa una regla.","explanation_feedback":"Incorrecta. No existe esa regla."},{"label":"C","text":"Porque el ion de zinc tiene carga 2+.","is_correct":false,"distractor_type":"Confunde la carga del ion con la razón del balance.","explanation_feedback":"Incorrecta. El coeficiente asegura la conservación de los átomos."},{"label":"D","text":"Para igualar los átomos de cloro e hidrógeno a cada lado.","is_correct":true,"distractor_type":null,"explanation_feedback":"Correcta. ZnCl₂ tiene 2 Cl y H₂ tiene 2 H; con 2 HCl el balance se cumple."}]'::jsonb, null, 1.3, 1.3, 0.25, 75, 'original_generated'
