select '0377cb51-1ca6-52e3-8999-5fa84214ec95', e.id, 'CN', (select id from public.content_components where code = 'CN.COMP.QUI'), 'qa_passed', 'continuous', '{"title":"Pastillas efervescentes","text":"Unos estudiantes quieren saber si la temperatura del agua afecta la rapidez con que se disuelve una pastilla efervescente. Ponen una pastilla igual en tres vasos con 200 mL de agua a 10 °C, 25 °C y 50 °C, y miden el tiempo que tarda en desaparecer.\nResultados: 10 °C: 95 s; 25 °C: 52 s; 50 °C: 24 s.","svg":null,"table":null}'::jsonb, '¿Por qué es importante que los tres vasos tengan la misma cantidad de agua y pastillas iguales?', '[{"label":"A","text":"Para que las tres pastillas se disuelvan al mismo tiempo.","is_correct":false,"distractor_type":"Anticipa un resultado.","explanation_feedback":"Incorrecta. Se espera que los tiempos cambien con la temperatura."},{"label":"B","text":"Porque así se gastan menos pastillas.","is_correct":false,"distractor_type":"Confunde control con ahorro.","explanation_feedback":"Incorrecta. El objetivo es comparar de manera justa."},{"label":"C","text":"Para que el experimento termine más rápido.","is_correct":false,"distractor_type":"Confunde control con rapidez.","explanation_feedback":"Incorrecta. Las cantidades iguales no buscan ahorrar tiempo."},{"label":"D","text":"Para que la temperatura sea la única variable que cambia entre los vasos.","is_correct":true,"distractor_type":null,"explanation_feedback":"Correcta. Controlar las demás variables permite atribuir las diferencias a la temperatura."}]'::jsonb, null, 1.1, 0, 0.25, 60, 'original_generated'
