select 'd6e0d46f-f1c2-552a-8be6-69427b26fe34', e.id, 'CN', (select id from public.content_components where code = 'CN.COMP.QUI'), 'qa_passed', 'continuous', '{"title":"Pastillas efervescentes","text":"Unos estudiantes quieren saber si la temperatura del agua afecta la rapidez con que se disuelve una pastilla efervescente. Ponen una pastilla igual en tres vasos con 200 mL de agua a 10 °C, 25 °C y 50 °C, y miden el tiempo que tarda en desaparecer.\nResultados: 10 °C: 95 s; 25 °C: 52 s; 50 °C: 24 s.","svg":null,"table":null}'::jsonb, 'Un estudiante concluye que «a 100 °C la pastilla se disolverá en 0 segundos». ¿Por qué no es válida esa conclusión?', '[{"label":"A","text":"Porque el experimento no midió tiempos.","is_correct":false,"distractor_type":"Contradice el texto.","explanation_feedback":"Incorrecta. Sí se midieron tiempos."},{"label":"B","text":"Porque la pastilla no se disuelve en agua caliente.","is_correct":false,"distractor_type":"Contradice los datos.","explanation_feedback":"Incorrecta. A 50 °C se disolvió más rápido."},{"label":"C","text":"Porque extrapola fuera del rango medido sin datos que lo respalden.","is_correct":true,"distractor_type":null,"explanation_feedback":"Correcta. Los datos llegan hasta 50 °C; no permiten afirmar un tiempo de 0 s a 100 °C."},{"label":"D","text":"Porque los datos muestran que el tiempo aumenta.","is_correct":false,"distractor_type":"Lee al revés los datos.","explanation_feedback":"Incorrecta. El tiempo disminuye."}]'::jsonb, null, 1.3, 1.3, 0.25, 75, 'original_generated'
