select 'cae6db57-6d46-5ac1-aae8-a5346fb1b8d3', e.id, 'CN', (select id from public.content_components where code = 'CN.COMP.QUI'), 'qa_passed', 'continuous', '{"title":"Cambios en la cocina","text":"Situaciones: (1) un cubo de hielo se derrite; (2) un pedazo de papel se quema; (3) la leche se agria; (4) el azúcar se disuelve en el café.","svg":null,"table":null}'::jsonb, '¿Qué evidencia indicaría que en la situación 3 hubo un cambio químico?', '[{"label":"A","text":"Cambios de olor y sabor y la formación de grumos que no desaparecen.","is_correct":true,"distractor_type":null,"explanation_feedback":"Correcta. Son señales de nuevas sustancias producidas por bacterias."},{"label":"B","text":"Que la leche sigue siendo líquida.","is_correct":false,"distractor_type":"Usa una evidencia que no muestra cambio.","explanation_feedback":"Incorrecta. Seguir líquida no indica reacción."},{"label":"C","text":"Que la leche se puede calentar.","is_correct":false,"distractor_type":"Usa una propiedad general.","explanation_feedback":"Incorrecta. Cualquier leche se puede calentar."},{"label":"D","text":"Que la leche está en un vaso.","is_correct":false,"distractor_type":"Usa un dato irrelevante.","explanation_feedback":"Incorrecta. El recipiente no indica un cambio químico."}]'::jsonb, null, 1.3, 1.3, 0.25, 60, 'original_generated'
