select 'd2eca637-edac-545a-8029-dd102cb2490e', e.id, 'CN', (select id from public.content_components where code = 'CN.COMP.QUI'), 'qa_passed', 'discontinuous', '{"title":"Densidad de los líquidos","text":null,"svg":null,"table":{"caption":"Densidad aproximada de algunos líquidos a 20 °C","headers":["Líquido","Densidad (g/mL)"],"rows":[["Aceite de cocina",0.92],["Agua",1],["Miel",1.42],["Alcohol etílico",0.79]]}}'::jsonb, 'Si en un vaso se echan miel, agua y aceite y se dejan reposar, ¿qué orden quedará de abajo hacia arriba?', '[{"label":"A","text":"Agua, miel y aceite.","is_correct":false,"distractor_type":"No compara bien las densidades.","explanation_feedback":"Incorrecta. La miel es más densa que el agua."},{"label":"B","text":"Miel, agua y aceite.","is_correct":true,"distractor_type":null,"explanation_feedback":"Correcta. Los líquidos más densos quedan abajo: 1,42 > 1,00 > 0,92."},{"label":"C","text":"Se mezclan y no forman capas.","is_correct":false,"distractor_type":"Ignora que el aceite no se mezcla con agua.","explanation_feedback":"Incorrecta. Forman capas por sus densidades y por no mezclarse."},{"label":"D","text":"Aceite, agua y miel.","is_correct":false,"distractor_type":"Invierte la relación entre densidad y posición.","explanation_feedback":"Incorrecta. El menos denso flota arriba."}]'::jsonb, null, 1.1, 0, 0.25, 60, 'original_generated'
