select '2d5aa8b3-57cf-5772-b048-8a4bc2f1915c', e.id, 'CN', (select id from public.content_components where code = 'CN.COMP.QUI'), 'qa_passed', 'discontinuous', '{"title":"Densidad de los líquidos","text":null,"svg":null,"table":{"caption":"Densidad aproximada de algunos líquidos a 20 °C","headers":["Líquido","Densidad (g/mL)"],"rows":[["Aceite de cocina",0.92],["Agua",1],["Miel",1.42],["Alcohol etílico",0.79]]}}'::jsonb, '¿Cuál es la masa de 50 mL de miel?', '[{"label":"A","text":"35 g.","is_correct":false,"distractor_type":"Divide el volumen entre la densidad.","explanation_feedback":"Incorrecta. Se multiplica, no se divide."},{"label":"B","text":"71 g.","is_correct":true,"distractor_type":null,"explanation_feedback":"Correcta. masa = densidad × volumen = 1,42 × 50 = 71 g."},{"label":"C","text":"50 g.","is_correct":false,"distractor_type":"Supone densidad 1.","explanation_feedback":"Incorrecta. La miel tiene densidad 1,42."},{"label":"D","text":"51,42 g.","is_correct":false,"distractor_type":"Suma en lugar de multiplicar.","explanation_feedback":"Incorrecta. La masa es el producto de densidad y volumen."}]'::jsonb, null, 1.3, 1.3, 0.25, 60, 'original_generated'
