select '5d040ccc-a58e-514b-87af-adccf05e85f7', e.id, 'CN', (select id from public.content_components where code = 'CN.COMP.QUI'), 'qa_passed', 'continuous', '{"title":"Lluvia ácida","text":"Al quemar combustibles con azufre se libera dióxido de azufre (SO₂). En el aire reacciona con agua y oxígeno y forma ácido sulfúrico, que cae con la lluvia. Esta lluvia ácida desgasta estatuas de mármol (carbonato de calcio, CaCO₃) y acidifica lagos.","svg":null,"table":null}'::jsonb, '¿Qué actividad humana origina el problema descrito?', '[{"label":"A","text":"Quemar combustibles que contienen azufre.","is_correct":true,"distractor_type":null,"explanation_feedback":"Correcta. El texto dice que así se libera el SO₂."},{"label":"B","text":"Construir estatuas de mármol.","is_correct":false,"distractor_type":"Confunde la víctima con la causa.","explanation_feedback":"Incorrecta. Las estatuas son afectadas, no la causa."},{"label":"C","text":"Sembrar árboles en las ciudades.","is_correct":false,"distractor_type":"Inventa una causa.","explanation_feedback":"Incorrecta. Los árboles no liberan SO₂."},{"label":"D","text":"Usar paneles solares.","is_correct":false,"distractor_type":"Inventa una causa.","explanation_feedback":"Incorrecta. Los paneles no queman combustible."}]'::jsonb, null, 1.1, 0, 0.25, 50, 'original_generated'
