select '9c42ad3a-2bab-5755-a60b-3be2fec4d1f7', e.id, 'CN', (select id from public.content_components where code = 'CN.COMP.QUI'), 'qa_passed', 'continuous', '{"title":"Lluvia ácida","text":"Al quemar combustibles con azufre se libera dióxido de azufre (SO₂). En el aire reacciona con agua y oxígeno y forma ácido sulfúrico, que cae con la lluvia. Esta lluvia ácida desgasta estatuas de mármol (carbonato de calcio, CaCO₃) y acidifica lagos.","svg":null,"table":null}'::jsonb, '¿Por qué las estatuas de mármol se desgastan con la lluvia ácida?', '[{"label":"A","text":"Porque el mármol se derrite con el sol.","is_correct":false,"distractor_type":"Confunde con fusión.","explanation_feedback":"Incorrecta. El mármol no se derrite con el sol."},{"label":"B","text":"Porque el agua de lluvia es más pesada que el mármol.","is_correct":false,"distractor_type":"Usa una explicación física incorrecta.","explanation_feedback":"Incorrecta. No es un efecto de peso."},{"label":"C","text":"Porque el SO₂ es un metal que raya la piedra.","is_correct":false,"distractor_type":"Clasifica mal el SO₂.","explanation_feedback":"Incorrecta. El SO₂ es un gas, no un metal."},{"label":"D","text":"Porque el ácido reacciona con el carbonato de calcio y lo transforma en otras sustancias.","is_correct":true,"distractor_type":null,"explanation_feedback":"Correcta. Es una reacción química entre un ácido y un carbonato."}]'::jsonb, null, 1.3, 1.3, 0.25, 75, 'original_generated'
