select 'ba41505a-27aa-5bd9-b181-744f2462c776', e.id, 'CN', (select id from public.content_components where code = 'CN.COMP.QUI'), 'qa_passed', 'continuous', '{"title":"Separar agua y alcohol","text":"El agua hierve a 100 °C y el etanol a 78 °C. Una mezcla de ambos se calienta lentamente en un equipo de destilación: el vapor pasa por un tubo frío, se condensa y se recoge en otro recipiente.","svg":null,"table":null}'::jsonb, '¿Qué sustancia se recoge primero en mayor proporción?', '[{"label":"A","text":"El etanol, porque tiene menor punto de ebullición.","is_correct":true,"distractor_type":null,"explanation_feedback":"Correcta. Se evapora primero el componente que hierve a menor temperatura."},{"label":"B","text":"Las dos al mismo tiempo y en igual cantidad.","is_correct":false,"distractor_type":"Ignora la diferencia de puntos de ebullición.","explanation_feedback":"Incorrecta. Hierven a temperaturas distintas."},{"label":"C","text":"El agua, porque es la más abundante.","is_correct":false,"distractor_type":"Usa la cantidad en lugar del punto de ebullición.","explanation_feedback":"Incorrecta. La separación depende de los puntos de ebullición."},{"label":"D","text":"Ninguna, porque el agua y el alcohol no se evaporan.","is_correct":false,"distractor_type":"Contradice el proceso.","explanation_feedback":"Incorrecta. Ambas se evaporan al calentarse lo suficiente."}]'::jsonb, null, 1.1, 0, 0.25, 60, 'original_generated'
