select '54f1cf2f-98cf-57fc-b5b8-96300f6c2f69', e.id, 'CN', (select id from public.content_components where code = 'CN.COMP.QUI'), 'qa_passed', 'continuous', '{"title":"Separar agua y alcohol","text":"El agua hierve a 100 °C y el etanol a 78 °C. Una mezcla de ambos se calienta lentamente en un equipo de destilación: el vapor pasa por un tubo frío, se condensa y se recoge en otro recipiente.","svg":null,"table":null}'::jsonb, '¿Para qué sirve el tubo frío del equipo?', '[{"label":"A","text":"Para condensar el vapor y volverlo líquido.","is_correct":true,"distractor_type":null,"explanation_feedback":"Correcta. Al enfriarse, el vapor pasa a estado líquido."},{"label":"B","text":"Para calentar más la mezcla.","is_correct":false,"distractor_type":"Invierte su función.","explanation_feedback":"Incorrecta. El tubo enfría."},{"label":"C","text":"Para filtrar las partículas sólidas.","is_correct":false,"distractor_type":"Confunde con un filtro.","explanation_feedback":"Incorrecta. No retiene sólidos."},{"label":"D","text":"Para que el alcohol se congele.","is_correct":false,"distractor_type":"Exagera el enfriamiento.","explanation_feedback":"Incorrecta. Solo se condensa a líquido."}]'::jsonb, null, 1.1, 0, 0.25, 45, 'original_generated'
