select '15e21419-6d4f-5cf2-9076-6c8dcc1044bd', e.id, 'CN', (select id from public.content_components where code = 'CN.COMP.QUI'), 'qa_passed', 'continuous', '{"title":"¿Cuánta agua se forma?","text":"El hidrógeno reacciona con el oxígeno según 2 H₂ + O₂ → 2 H₂O. Masas molares: H₂ = 2 g/mol, O₂ = 32 g/mol, H₂O = 18 g/mol. En un recipiente hay 4 g de H₂ y 16 g de O₂.","svg":null,"table":null}'::jsonb, '¿Cuál de los reactivos se acaba primero?', '[{"label":"A","text":"El hidrógeno (H₂).","is_correct":false,"distractor_type":"Compara masas en lugar de moles.","explanation_feedback":"Incorrecta. Aunque hay menos gramos de H₂, hay más moles."},{"label":"B","text":"El oxígeno (O₂).","is_correct":true,"distractor_type":null,"explanation_feedback":"Correcta. Hay 2 mol de H₂ y 0,5 mol de O₂; 2 mol de H₂ necesitarían 1 mol de O₂, así que falta oxígeno."},{"label":"C","text":"No se acaba ninguno.","is_correct":false,"distractor_type":"Desconoce el reactivo limitante.","explanation_feedback":"Incorrecta. Uno de los dos limita la reacción."},{"label":"D","text":"Se acaban los dos al mismo tiempo.","is_correct":false,"distractor_type":"Supone proporción exacta.","explanation_feedback":"Incorrecta. La proporción necesaria es 2:1 en moles y aquí es 4:1."}]'::jsonb, null, 1.3, 1.3, 0.25, 90, 'original_generated'
