select '179bf68c-6508-57ef-8a2f-9bfc977f9b31', e.id, 'CN', (select id from public.content_components where code = 'CN.COMP.QUI'), 'qa_passed', 'continuous', '{"title":"¿Cuánta agua se forma?","text":"El hidrógeno reacciona con el oxígeno según 2 H₂ + O₂ → 2 H₂O. Masas molares: H₂ = 2 g/mol, O₂ = 32 g/mol, H₂O = 18 g/mol. En un recipiente hay 4 g de H₂ y 16 g de O₂.","svg":null,"table":null}'::jsonb, '¿Cuántos gramos de agua se pueden formar como máximo?', '[{"label":"A","text":"18 g.","is_correct":true,"distractor_type":null,"explanation_feedback":"Correcta. 0,5 mol de O₂ forman 1 mol de H₂O, es decir 18 g."},{"label":"B","text":"36 g.","is_correct":false,"distractor_type":"Supone que reacciona todo el hidrógeno.","explanation_feedback":"Incorrecta. El oxígeno alcanza solo para 1 mol de agua."},{"label":"C","text":"9 g.","is_correct":false,"distractor_type":"Usa 0,5 mol de agua.","explanation_feedback":"Incorrecta. Cada mol de O₂ produce 2 mol de agua."},{"label":"D","text":"20 g.","is_correct":false,"distractor_type":"Suma las masas de los reactivos.","explanation_feedback":"Incorrecta. Sobra hidrógeno; no todo reacciona."}]'::jsonb, null, 1.3, 1.3, 0.25, 90, 'original_generated'
