select '1c18249d-9f32-5383-9d2b-36fb90f1dbb1', e.id, 'CN', (select id from public.content_components where code = 'CN.COMP.QUI'), 'qa_passed', 'continuous', '{"title":"La tabla periódica","text":"En la tabla periódica, los elementos de una misma columna (grupo) tienen el mismo número de electrones en su capa más externa y por eso tienen propiedades químicas parecidas. El litio, el sodio y el potasio están en el grupo 1 y tienen un electrón externo. El flúor y el cloro están en el grupo 17 y tienen siete electrones externos.","svg":null,"table":null}'::jsonb, '¿Por qué el sodio y el potasio reaccionan de forma parecida con el agua?', '[{"label":"A","text":"Porque tienen el mismo número de protones.","is_correct":false,"distractor_type":"Confunde grupo con identidad del elemento.","explanation_feedback":"Incorrecta. Cada elemento tiene un número distinto de protones."},{"label":"B","text":"Porque tienen la misma masa.","is_correct":false,"distractor_type":"Atribuye las propiedades a la masa.","explanation_feedback":"Incorrecta. Sus masas son distintas."},{"label":"C","text":"Porque están en el mismo grupo y tienen un electrón externo.","is_correct":true,"distractor_type":null,"explanation_feedback":"Correcta. Igual número de electrones externos produce propiedades químicas parecidas."},{"label":"D","text":"Porque los dos son gases.","is_correct":false,"distractor_type":"Clasifica mal los elementos.","explanation_feedback":"Incorrecta. Son metales sólidos."}]'::jsonb, null, 1.1, 0, 0.25, 60, 'original_generated'
