select 'b8c2cfc3-cba8-5692-8c4e-dfce3b06b0bb', e.id, 'CN', (select id from public.content_components where code = 'CN.COMP.QUI'), 'qa_passed', 'continuous', '{"title":"La tabla periódica","text":"En la tabla periódica, los elementos de una misma columna (grupo) tienen el mismo número de electrones en su capa más externa y por eso tienen propiedades químicas parecidas. El litio, el sodio y el potasio están en el grupo 1 y tienen un electrón externo. El flúor y el cloro están en el grupo 17 y tienen siete electrones externos.","svg":null,"table":null}'::jsonb, '¿Qué ion tiende a formar el cloro y por qué?', '[{"label":"A","text":"No forma iones porque es un gas.","is_correct":false,"distractor_type":"Confunde estado con reactividad.","explanation_feedback":"Incorrecta. El cloro sí forma iones."},{"label":"B","text":"Cl⁺, porque pierde un electrón.","is_correct":false,"distractor_type":"Invierte la tendencia.","explanation_feedback":"Incorrecta. Perder siete o ganar uno: gana uno."},{"label":"C","text":"Cl⁻, porque gana un electrón para completar ocho en su capa externa.","is_correct":true,"distractor_type":null,"explanation_feedback":"Correcta. Con siete electrones externos, le es más fácil ganar uno."},{"label":"D","text":"Cl⁷⁺, porque pierde los siete electrones.","is_correct":false,"distractor_type":"Supone que pierde todos los externos.","explanation_feedback":"Incorrecta. Es más fácil ganar un electrón."}]'::jsonb, null, 1.3, 1.3, 0.25, 75, 'original_generated'
